/* Block Counting – Isometric Scene Container */
.bc-scene {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 0.75rem;
  border-radius: 0.75rem;
  background: radial-gradient(circle at top, #1f2933 0%, #020617 60%);
  border: 1px solid #334155;
  box-shadow: 0 16px 40px rgba(15, 23, 42, 0.8);
}

.bc-legend {
  font-size: 11px;
  line-height: 1.3;
  color: #cbd5f5;
}

.bc-legend-line {
  opacity: 0.85;
}

/* Grid for cube columns */
.bc-grid {
  position: relative;
  width: 100%;
  height: 220px;
  overflow: visible;
}

/* One floor column of cubes */
.bc-column {
  position: absolute;
  transform-origin: bottom center;
}

/* Single cube (top face is the element itself) */
.bc-cube {
  position: absolute;
  width: 40px;
  height: 23px; /* top face height in isometric view */
  background: linear-gradient(135deg, #22c55e, #4ade80);
  transform: skewY(-30deg) skewX(-45deg);
  box-shadow: 0 6px 10px rgba(15, 23, 42, 0.9);
}

/* Left face */
.bc-cube::before {
  content: "";
  position: absolute;
  top: 100%;
  left: 0;
  width: 40px;
  height: 30px;
  background: linear-gradient(180deg, #15803d, #052e16);
  transform-origin: top left;
  transform: skewY(30deg);
}

/* Right face */
.bc-cube::after {
  content: "";
  position: absolute;
  top: 0;
  left: 100%;
  width: 40px;
  height: 30px;
  background: linear-gradient(180deg, #16a34a, #052e16);
  transform-origin: top left;
  transform: skewX(45deg);
}

/* Level offset – higher levels stack upward */
.bc-cube[class*="bc-cube-level"] {
  /* baseline Y (bottom level) will be set from the column itself */
}

/* Example vertical offsets (Copilot can compute exact translateY per level) */
.bc-cube-level0 { transform: translateY(0) skewY(-30deg) skewX(-45deg); }
.bc-cube-level1 { transform: translateY(-22px) skewY(-30deg) skewX(-45deg); }
.bc-cube-level2 { transform: translateY(-44px) skewY(-30deg) skewX(-45deg); }
.bc-cube-level3 { transform: translateY(-66px) skewY(-30deg) skewX(-45deg); }

/* Column position helpers (Copilot should generate inline styles or extra classes) */
/* Horizontal spacing by col index, vertical depth by row index */
/* Example for a 3x2 grid: */
.bc-column-col0-row0 { left: 80px; bottom: 40px; }
.bc-column-col1-row0 { left: 110px; bottom: 52px; }
.bc-column-col2-row0 { left: 140px; bottom: 64px; }
.bc-column-col0-row1 { left: 70px; bottom: 70px; }
.bc-column-col1-row1 { left: 100px; bottom: 82px; }
.bc-column-col2-row1 { left: 130px; bottom: 94px; }

